examples.code:
#include <sstream>
#include <utility>
#include <cassert>
#include <iostream>

int main() {
    std::stringstream stream{"42"};

    int value{};
    stream >> value;
    assert(value == 42);
    assert(stream.rdbuf() != nullptr);
    std::stringstream other;
    other = std::move(stream);
    other.swap(stream);
    std::swap(other, stream);
    std::cout << "Checks passed\n";
}
